import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <algorithm>
#define BN_THREADS 256
__device__ __forceinline__ void warp_reduce2(float& s, float& q) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        s += __shfl_down_sync(0xffffffffu, s, offset);
        q += __shfl_down_sync(0xffffffffu, q, offset);
    }
}
__global__ void __launch_bounds__(BN_THREADS) bn2d_reduce_kernel(
    const float* __restrict__ x,
    float* __restrict__ g_sum,
    float* __restrict__ g_sumsq,
    float* __restrict__ g_counter,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int64_t* __restrict__ num_batches_tracked,
    float* __restrict__ g_norm_mean,
    float* __restrict__ g_norm_inv,
    const int N,
    const int C,
    const long long S,
    const float momentum,
    const float eps)
{
    const long long slice = (long long)blockIdx.x;
    const long long total_slices = (long long)N * (long long)C;
    if (slice >= total_slices) return;
    const int tid = threadIdx.x;
    const int c = (int)(slice % (long long)C);
    const long long base = slice * S;
    float partial_sum = 0.0f;
    float partial_sumsq = 0.0f;
    if ((S & 3LL) == 0LL) {
        const long long S4 = S >> 2;
        const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x + base);
        float sum0 = 0.0f, sum1 = 0.0f, sum2 = 0.0f, sum3 = 0.0f;
        float sq0 = 0.0f, sq1 = 0.0f, sq2 = 0.0f, sq3 = 0.0f;
        const long long stride = (long long)blockDim.x;
        const long long unroll = stride << 2;
        long long s4 = tid;
        for (; s4 + 3 * stride < S4; s4 += unroll) {
            const float4 v0 = __ldcs(&x4[s4]);
            const float4 v1 = __ldcs(&x4[s4 + stride]);
            const float4 v2 = __ldcs(&x4[s4 + 2 * stride]);
            const float4 v3 = __ldcs(&x4[s4 + 3 * stride]);
            sum0 += (v0.x + v0.y) + (v0.z + v0.w);
            sum1 += (v1.x + v1.y) + (v1.z + v1.w);
            sum2 += (v2.x + v2.y) + (v2.z + v2.w);
            sum3 += (v3.x + v3.y) + (v3.z + v3.w);
            sq0 += (v0.x * v0.x + v0.y * v0.y) + (v0.z * v0.z + v0.w * v0.w);
            sq1 += (v1.x * v1.x + v1.y * v1.y) + (v1.z * v1.z + v1.w * v1.w);
            sq2 += (v2.x * v2.x + v2.y * v2.y) + (v2.z * v2.z + v2.w * v2.w);
            sq3 += (v3.x * v3.x + v3.y * v3.y) + (v3.z * v3.z + v3.w * v3.w);
        }
        for (; s4 < S4; s4 += stride) {
            const float4 v = __ldcs(&x4[s4]);
            sum0 += (v.x + v.y) + (v.z + v.w);
            sq0 += (v.x * v.x + v.y * v.y) + (v.z * v.z + v.w * v.w);
        }
        partial_sum = ((sum0 + sum1) + (sum2 + sum3));
        partial_sumsq = ((sq0 + sq1) + (sq2 + sq3));
    } else {
        for (long long s = tid; s < S; s += blockDim.x) {
            const float v = __ldcs(&x[base + s]);
            partial_sum += v;
            partial_sumsq += v * v;
        }
    }
    __shared__ float red_sum[BN_THREADS / 32];
    __shared__ float red_sumsq[BN_THREADS / 32];
    warp_reduce2(partial_sum, partial_sumsq);
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int num_warps = (int)(blockDim.x >> 5);
    if (lane == 0) {
        red_sum[warp] = partial_sum;
        red_sumsq[warp] = partial_sumsq;
    }
    __syncthreads();
    if (warp == 0) {
        float s = (lane < num_warps) ? red_sum[lane] : 0.0f;
        float sq = (lane < num_warps) ? red_sumsq[lane] : 0.0f;
        warp_reduce2(s, sq);
        if (lane == 0) {
            atomicAdd(&g_sum[c], s);
            atomicAdd(&g_sumsq[c], sq);
            __threadfence();
            const float prev = atomicAdd(&g_counter[c], 1.0f);
            if (prev == (float)(N - 1)) {
                const float tot_s = atomicAdd(&g_sum[c], 0.0f);
                const float tot_sq = atomicAdd(&g_sumsq[c], 0.0f);
                const float count = (float)((long long)N * S);
                const float inv_count = 1.0f / count;
                const float mean = tot_s * inv_count;
                float var = tot_sq * inv_count - mean * mean;
                var = fmaxf(var, 0.0f);
                const float unbiased_var = (count > 1.0f) ? (var * count / (count - 1.0f)) : var;
                running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * mean;
                running_var[c] = (1.0f - momentum) * running_var[c] + momentum * unbiased_var;
                g_norm_mean[c] = mean;
                g_norm_inv[c] = rsqrtf(var + eps);
                if (c == 0) {
                    *num_batches_tracked += 1;
                }
            }
        }
    }
}
__global__ void bn2d_finalize_kernel(
    const float* __restrict__ g_sum,
    const float* __restrict__ g_sumsq,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int64_t* __restrict__ num_batches_tracked,
    float* __restrict__ g_norm_mean,
    float* __restrict__ g_norm_inv,
    const int N,
    const int C,
    const long long S,
    const double momentum,
    const double eps,
    const bool training)
{
    const int c = (int)blockIdx.x;
    if (c >= C) return;
    const int tid = threadIdx.x;
    if (training) {
        const int lane = tid & 31;
        const int warp = tid >> 5;
        const int num_warps = (int)(blockDim.x >> 5);
        float partial_sum = 0.0f;
        float partial_sumsq = 0.0f;
        for (int n = tid; n < N; n += (int)blockDim.x) {
            const long long idx = (long long)n * (long long)C + (long long)c;
            partial_sum += g_sum[idx];
            partial_sumsq += g_sumsq[idx];
        }
        __shared__ float red_sum[BN_THREADS / 32];
        __shared__ float red_sumsq[BN_THREADS / 32];
        warp_reduce2(partial_sum, partial_sumsq);
        if (lane == 0) {
            red_sum[warp] = partial_sum;
            red_sumsq[warp] = partial_sumsq;
        }
        __syncthreads();
        if (warp == 0) {
            float s = (lane < num_warps) ? red_sum[lane] : 0.0f;
            float sq = (lane < num_warps) ? red_sumsq[lane] : 0.0f;
            warp_reduce2(s, sq);
            if (lane == 0) {
                const float count = (float)((long long)N * S);
                const float inv_count = 1.0f / count;
                const float mean = s * inv_count;
                float var = sq * inv_count - mean * mean;
                var = fmaxf(var, 0.0f);
                const float mom = (float)momentum;
                const float unbiased_var = (count > 1.0f) ? (var * count / (count - 1.0f)) : var;
                running_mean[c] = (1.0f - mom) * running_mean[c] + mom * mean;
                running_var[c] = (1.0f - mom) * running_var[c] + mom * unbiased_var;
                g_norm_mean[c] = mean;
                g_norm_inv[c] = rsqrtf(var + (float)eps);
            }
        }
    } else {
        if (tid == 0) {
            g_norm_mean[c] = running_mean[c];
            g_norm_inv[c] = rsqrtf(running_var[c] + (float)eps);
        }
    }
    if (training && blockIdx.x == 0 && threadIdx.x == 0) {
        *num_batches_tracked += 1;
    }
}
__global__ void __launch_bounds__(BN_THREADS) bn2d_normalize_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ g_norm_mean,
    const float* __restrict__ g_norm_inv,
    const int N,
    const int C,
    const long long S)
{
    const long long slice = (long long)blockIdx.x;
    const long long total_slices = (long long)N * (long long)C;
    if (slice >= total_slices) return;
    const int tid = threadIdx.x;
    const int c = (int)(slice % (long long)C);
    const long long base = slice * S;
    const float mean = g_norm_mean[c];
    const float inv_std = g_norm_inv[c];
    const float gamma = weight[c];
    const float beta = bias[c];
    const float scale = inv_std * gamma;
    const float shift = fmaf(-mean, scale, beta);
    if ((S & 3LL) == 0LL) {
        const long long S4 = S >> 2;
        const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x + base);
        float4* __restrict__ y4 = reinterpret_cast<float4*>(y + base);
        const long long stride = (long long)blockDim.x;
        const long long unroll = stride << 2;
        long long s4 = tid;
        for (; s4 + 3 * stride < S4; s4 += unroll) {
            const float4 v0 = __ldcs(&x4[s4]);
            const float4 v1 = __ldcs(&x4[s4 + stride]);
            const float4 v2 = __ldcs(&x4[s4 + 2 * stride]);
            const float4 v3 = __ldcs(&x4[s4 + 3 * stride]);
            float4 r0, r1, r2, r3;
            r0.x = fmaf(v0.x, scale, shift);
            r0.y = fmaf(v0.y, scale, shift);
            r0.z = fmaf(v0.z, scale, shift);
            r0.w = fmaf(v0.w, scale, shift);
            r1.x = fmaf(v1.x, scale, shift);
            r1.y = fmaf(v1.y, scale, shift);
            r1.z = fmaf(v1.z, scale, shift);
            r1.w = fmaf(v1.w, scale, shift);
            r2.x = fmaf(v2.x, scale, shift);
            r2.y = fmaf(v2.y, scale, shift);
            r2.z = fmaf(v2.z, scale, shift);
            r2.w = fmaf(v2.w, scale, shift);
            r3.x = fmaf(v3.x, scale, shift);
            r3.y = fmaf(v3.y, scale, shift);
            r3.z = fmaf(v3.z, scale, shift);
            r3.w = fmaf(v3.w, scale, shift);
            __stcs(&y4[s4], r0);
            __stcs(&y4[s4 + stride], r1);
            __stcs(&y4[s4 + 2 * stride], r2);
            __stcs(&y4[s4 + 3 * stride], r3);
        }
        for (; s4 < S4; s4 += stride) {
            const float4 v = __ldcs(&x4[s4]);
            float4 r;
            r.x = fmaf(v.x, scale, shift);
            r.y = fmaf(v.y, scale, shift);
            r.z = fmaf(v.z, scale, shift);
            r.w = fmaf(v.w, scale, shift);
            __stcs(&y4[s4], r);
        }
    } else {
        for (long long s = tid; s < S; s += blockDim.x) {
            const long long idx = base + s;
            __stcs(&y[idx], fmaf(__ldcs(&x[idx]), scale, shift));
        }
    }
}
torch::Tensor batchnorm_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor num_batches_tracked,
    double momentum,
    double eps,
    bool training)
{
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only float32 is supported");
    TORCH_CHECK(x.dim() == 4, "expected NCHW input");
    TORCH_CHECK(x.is_contiguous(), "expected contiguous NCHW input");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "parameters must be CUDA");
    TORCH_CHECK(running_mean.is_cuda() && running_var.is_cuda(), "running stats must be CUDA");
    const int64_t N64 = x.size(0);
    const int64_t C64 = x.size(1);
    const int64_t H64 = x.size(2);
    const int64_t W64 = x.size(3);
    TORCH_CHECK(N64 > 0 && C64 > 0 && H64 > 0 && W64 > 0, "invalid input shape");
    TORCH_CHECK(C64 <= 2147483647LL, "too many channels");
    TORCH_CHECK(N64 * C64 <= 2147483647LL, "too many N*C slices");
    const int N = (int)N64;
    const int C = (int)C64;
    const long long S = (long long)(H64 * W64);
    const int total_slices = (int)(N64 * C64);
    auto y = at::empty_like(x);
    auto opts = x.options();
    auto g_norm_mean = at::empty({C64}, opts);
    auto g_norm_inv = at::empty({C64}, opts);
    const float* x_ptr = x.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();
    const float* w_ptr = weight.data_ptr<float>();
    const float* b_ptr = bias.data_ptr<float>();
    float* rm_ptr = running_mean.data_ptr<float>();
    float* rv_ptr = running_var.data_ptr<float>();
    int64_t* nbt_ptr = num_batches_tracked.data_ptr<int64_t>();
    float* nm_ptr = g_norm_mean.data_ptr<float>();
    float* ni_ptr = g_norm_inv.data_ptr<float>();
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    if (training) {
        auto workspace = at::zeros({3 * C64}, opts);
        float* gs_ptr = workspace.data_ptr<float>();
        float* gsq_ptr = gs_ptr + C64;
        float* gcnt_ptr = gs_ptr + 2 * C64;
        bn2d_reduce_kernel<<<total_slices, BN_THREADS, 0, stream>>>(
            x_ptr, gs_ptr, gsq_ptr, gcnt_ptr, rm_ptr, rv_ptr, nbt_ptr, nm_ptr, ni_ptr,
            N, C, S, (float)momentum, (float)eps);
        cudaError_t err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
    } else {
        const int fin_blocks = (int)C64;
        bn2d_finalize_kernel<<<fin_blocks, BN_THREADS, 0, stream>>>(
            nullptr, nullptr, rm_ptr, rv_ptr, nbt_ptr, nm_ptr, ni_ptr, N, C, S, momentum, eps, training);
        cudaError_t err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
    }
    bn2d_normalize_kernel<<<total_slices, BN_THREADS, 0, stream>>>(x_ptr, y_ptr, w_ptr, b_ptr, nm_ptr, ni_ptr, N, C, S);
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
    return y;
}
